head.script:
scwin.labelFormatter = function(itemArr) { //debugger;
    console.log("labelformatter");
    var customArr = itemArr;
    for (var i = 0; i < itemArr.length; i++) {
        customArr[i].label = itemArr[i].label + "커스텀적용아이템";
    }
    return customArr;
}
scwin.selectbox1_onviewchange = function(info) {
    console.log("oldValue#####" + info.oldValue + "newValue#####" + info.newValue);
    log = "oldValue#####" + info.oldValue + "newValue#####" + info.newValue;
};
scwin.selectbox1_onchange = function() {
    console.log("onchange");
};
scwin.trigger1_onclick = function(e) { //debugger;
    selectbox1.setNodeSet('data:dataList3', 'label', 'value');
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 1번샘플 실행 후 inputbox에 '1'값을 입력후 enterkey 입력한다.
    //1. After executing sample 1, input '1' value to inputbox and enter enterkey.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').setValue('1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. selectbox에 '1번커스텀적용아이템'값이 적용되어 보여진다.
    //1. The 'custom item 1' item is applied to the selectbox.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1_label').innerText == '1번커스텀적용아이템'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'setnodeset'버튼을 클릭한다.
    //2. Click the 'setnodeset' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. selectbox에 '1_2커스텀적용아이템'값이 적용되어 보여진다.
    //2. The '1_2 Custom Applied Item' value is applied to the selectbox.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1_label').innerText == '1_2커스텀적용아이템'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. selectbox를 클릭하여 값을 변경(예 : 2_2)한다.
    //3. Click on selectbox to change the value (eg 2_2).
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. selectbox에 '2_2커스텀적용아이템'값이 적용되어 변경되어지고 console에 이전값과 이후값이 보여진다. oldValue#####1newValue#####2
    //3. The '2_2 Custom Applied Item' value is applied to the selectbox and the previous value and the subsequent value are displayed on the console. oldValue ##### 1newValue ##### 2
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1_label').innerText == '2_2커스텀적용아이템'", "true");
    WebSquare.wUnit.addCommand("assert", "log", "oldValue#####1newValue#####2");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 12-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
